"""Generate a self-contained guide using the actual saved model outputs."""
from pathlib import Path
import json
import joblib
import numpy as np
import pandas as pd
from project_config import FEATURE_DETAILS, FEATURE_COLUMNS

ROOT = Path(__file__).resolve().parent
data = json.loads((ROOT / 'model/evaluation.json').read_text(encoding='utf-8'))
rf = joblib.load(ROOT / 'model/cyber_model.joblib')
lr = joblib.load(ROOT / 'model/logistic_model.joblib')
names = lr.named_steps['preprocessor'].get_feature_names_out()
classifier = lr.named_steps['classifier']
for case in data['cases']:
    row = pd.DataFrame([case['features']], columns=FEATURE_COLUMNS)
    encoded = lr.named_steps['preprocessor'].transform(row)
    encoded = encoded.toarray() if hasattr(encoded, 'toarray') else encoded
    contributions = encoded[0] * classifier.coef_[0]
    forest_input = rf.named_steps['preprocessor'].transform(row)
    tree_probabilities = [float(tree.predict_proba(forest_input)[0, 1]) for tree in rf.named_steps['classifier'].estimators_]
    case['calculation'] = {
        'logit': float(classifier.intercept_[0] + contributions.sum()),
        'intercept': float(classifier.intercept_[0]),
        'terms': [dict(feature=str(name).split('__', 1)[-1], transformed_value=float(value), coefficient=float(coefficient), contribution=float(contribution)) for name, value, coefficient, contribution in zip(names, encoded[0], classifier.coef_[0], contributions)],
        'tree_min': min(tree_probabilities), 'tree_max': max(tree_probabilities),
        'tree_mean': float(np.mean(tree_probabilities)),
    }
data['features'] = [dict(zip(['name', 'group', 'type', 'meaning', 'significance'], entry), importance=data['grouped_importance'][entry[0]]) for entry in FEATURE_DETAILS]

